export interface ShortcutConfig {
  action: ActionConfig;
  trigger: TriggerConfig;
}
export interface TriggerConfig {
  key: KeyName;
  mods?: TriggerModifier[];
}
/**
 * `settings.json`.
 */
export interface Settings {
  /**
   * Optional editor hint pointing at the JSON Schema; ignored by Keyrift.
   */
  $schema?: string | null;
  /**
   * File name (without `.json`) of the active profile in `profiles/`.
   */
  activeProfile?: string;
  devices?: DeviceSettings;
  emergencyRelease?: EmergencyRelease;
  logLevel?: "error" | "warn" | "info" | "debug";
  tapHold?: TapHoldDefaults;
  ui?: UiSettings;
  version?: number;
}
export interface DeviceSettings {
  /**
   * Keyboards that are never grabbed.
   */
  excluded?: DeviceMatch[];
  /**
   * Hidden devices (e.g. mice with a keyboard interface) that should be grabbed anyway.
   */
  included?: DeviceMatch[];
}
/**
 * Identifies a keyboard by vendor ID, product ID and name (never by port).
 */
export interface DeviceMatch {
  name: string;
  /**
   * Hex, e.g. "0x16d2".
   */
  productId: string;
  /**
   * Hex, e.g. "0x0951".
   */
  vendorId: string;
}
export interface EmergencyRelease {
  enabled?: boolean;
  /**
   * Physical keys that, held together, release all keyboards.
   */
  keys?: KeyName[];
}
export interface TapHoldDefaults {
  strategy?: "permissive-hold" | "hold-on-other-press" | "timeout-only";
  timeoutMs?: number;
}
/**
 * Settings used only by the GUI.
 */
export interface UiSettings {
  notifyLayerToggle?: boolean;
  physicalLayout?: string;
  theme?: "system" | "light" | "dark";
}
